import { test, expect } from '@playwright/test';

test.describe('Login Form', () => {
  test('should log in with valid credentials', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
    await page.fill('#username', 'tomsmith');
    await page.fill('#password', 'SuperSecretPassword!');
    await page.click('button.radius');
    await expect(page).not.toHaveURL(/login/);
  });

  test('should not log in with invalid credentials', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
    await page.fill('#username', 'invalidUser');
    await page.fill('#password', 'invalidPassword');
    await page.click('button.radius');
    await expect(page).toHaveURL(/login/);
    await expect(page.locator('#flash-messages')).toBeVisible();
  });
});

describe('Checkboxes Form', () => {
  it('should allow the user to check and uncheck checkboxes', () => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
    cy.get('input[type="checkbox"]').first().check();
    cy.get('input[type="checkbox"]').first().should('be.checked');
    cy.get('input[type="checkbox"]').first().uncheck();
    cy.get('input[type="checkbox"]').first().should('not.be.checked');
  });
  it('should not change the URL when checkboxes are interacted with', () => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
    cy.get('input[type="checkbox"]').first().check();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/checkboxes');
  });
});

describe('Add and Remove Elements', () => {
  it('should add an element when the button is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('button').contains('Add Element').click();
    cy.get('#elements').children().should('have.length', 1);
  });

  it('should remove an element when it is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('button').contains('Add Element').click();
    cy.get('#elements').children().first().click();
    cy.get('#elements').children().should('have.length', 0);
  });
});

describe('JavaScript Alerts', () => {
  it('should display an alert and accept it', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Alert').click();
    cy.on('window:alert', (text) => {
      expect(text).to.eq('I am a JS Alert');
    });
    cy.get('#result').should('be.visible');
  });

  it('should display a confirm dialog and accept it', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Confirm').click();
    cy.on('window:confirm', () => true);
    cy.get('#result').should('be.visible');
  });
});

import { test, expect } from '@playwright/test';

test.describe('JavaScript Alerts', () => {
  test('should display an alert and accept it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    page.on('dialog', async dialog => {
      expect(dialog.message()).toBe('I am a JS Alert');
      await dialog.accept();
    });
    await page.click('button:has-text("Click for JS Alert")');
    const result = await page.locator('#result');
    await expect(result).toBeVisible();
  });

  test('should display a confirm dialog and accept it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    page.on('dialog', async dialog => {
      await dialog.accept();
    });
    await page.click('button:has-text("Click for JS Confirm")');
    const result = await page.locator('#result');
    await expect(result).toBeVisible();
  });
});
